'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(boxed=false){const frames=new Map();let clock=0,serial=0;const stage={classList:{contains:name=>boxed&&name==='phoenix-horizontal-box'},listeners:new Map(),addEventListener(name,cb){this.listeners.set(name,cb);},setPointerCapture(id){this.capture=id;},hasPointerCapture(id){return this.capture===id;},releasePointerCapture(){this.capture=null;}};const window={matchMedia:()=>({matches:false,addEventListener(){}}),performance:{now:()=>clock},requestAnimationFrame(cb){const id=++serial;frames.set(id,cb);return id;},cancelAnimationFrame(id){frames.delete(id);}};vm.runInNewContext(fs.readFileSync('deck-motion.js','utf8'),{window});const {DeckMotion,bindDrag}=window.PhoenixDeckMotion,motion=new DeckMotion();bindDrag(stage,motion,{paint(){},save(){},pixelsPerCard:()=>100});function fire(name,props={}){let blocked=false;const event={isPrimary:true,button:0,pointerId:1,clientX:200,clientY:100,timeStamp:clock,preventDefault(){blocked=true;},stopImmediatePropagation(){blocked=true;},...props};stage.listeners.get(name)?.(event);return blocked;}return {motion,stage,fire,frames,frame(dt){clock+=dt;const list=[...frames.values()];frames.clear();list.forEach(cb=>cb(clock));}};}
test('drag follows pointer immediately and release continues with momentum without snapping',()=>{const x=setup();x.fire('pointerdown');x.fire('pointermove',{clientX:165,timeStamp:16});assert.equal(x.motion.position,.35);assert.equal(x.stage.capture,1);x.fire('pointerup',{clientX:165,timeStamp:20});assert.ok(x.frames.size);const before=x.motion.position;x.frame(16);assert.ok(x.motion.position>before);assert.equal(x.fire('click'),true);});
test('first tap catches momentum without activating; a second deliberate tap can activate',()=>{const x=setup();x.motion.release(.01,false);x.fire('pointerdown');x.fire('pointerup');assert.equal(x.motion.velocity,0);assert.equal(x.fire('click'),true);x.fire('pointerdown');x.fire('pointerup');assert.equal(x.fire('click'),false);});
test('vertical gesture never rotates deck or activates a card; cancelled drag has no inertia',()=>{const x=setup();x.fire('pointerdown');x.fire('pointermove',{clientY:125,clientX:201});x.fire('pointerup');assert.equal(x.motion.position,0);assert.equal(x.fire('click'),true);x.fire('pointerdown');x.fire('pointermove',{clientX:180,timeStamp:16});x.fire('pointercancel');assert.equal(x.frames.size,0);assert.equal(x.motion.velocity,0);});
test('ambiguous diagonal movement waits for clearer intent and never activates a card',()=>{const x=setup();x.fire('pointerdown');x.fire('pointermove',{clientX:209,clientY:111,timeStamp:16});assert.equal(x.motion.position,0);assert.equal(x.stage.capture,undefined);x.fire('pointerup');assert.equal(x.fire('click'),true);});
test('clear horizontal intent retains immediate drag without vertical page ownership',()=>{const x=setup();x.fire('pointerdown');x.fire('pointermove',{clientX:180,clientY:105,timeStamp:16});assert.equal(x.motion.position,.2);assert.equal(x.stage.capture,1);x.fire('pointerup',{timeStamp:100});assert.equal(x.fire('click'),true);});
test('native vertical cancellation rolls back an early horizontal movement without inertia',()=>{const x=setup();x.motion.position=2;x.fire('pointerdown');x.fire('pointermove',{clientX:180,clientY:103,timeStamp:16});assert.equal(x.motion.position,2.2);x.fire('pointercancel');assert.equal(x.motion.position,2);assert.equal(x.frames.size,0);assert.equal(x.fire('click'),true);});

test('enclosed deck follows a diagonal swipe without waiting for a stronger axis ratio',()=>{const x=setup(true);x.fire('pointerdown');x.fire('pointermove',{clientX:209,clientY:111,timeStamp:16});assert.equal(x.motion.position,-.09);assert.equal(x.stage.capture,1);x.fire('pointerup');assert.equal(x.fire('click'),true);});
test('enclosed deck can pick up horizontal movement after initial vertical drift',()=>{const x=setup(true);x.fire('pointerdown');x.fire('pointermove',{clientX:201,clientY:125,timeStamp:16});assert.equal(x.motion.position,0);x.fire('pointermove',{clientX:220,clientY:130,timeStamp:32});assert.equal(x.motion.position,-.2);assert.equal(x.stage.capture,1);x.fire('pointerup');assert.equal(x.fire('click'),true);});
test('a vertical-only swipe inside a box never rotates or activates a card',()=>{const x=setup(true);x.fire('pointerdown');x.fire('pointermove',{clientY:150,clientX:201});x.fire('pointerup');assert.equal(x.motion.position,0);assert.equal(x.stage.capture,undefined);assert.equal(x.fire('click'),true);assert.equal(x.frames.size,0);});
